<?php $e=static fn(mixed $v):string=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$v=static fn(string $k):string=>$e($values[$k]??''); ?>
<div class="page-heading"><div><h1><?= $e($title) ?></h1><p>Leave slug empty to generate it from the name.</p></div><a href="/admin/categories">Back to categories</a></div><?php if($errors):?><div class="flash flash-error" role="alert"><strong>Please correct the highlighted fields.</strong></div><?php endif;?>
<form class="panel admin-form" method="post" action="<?= $e($action) ?>"><input type="hidden" name="_csrf" value="<?= $e($csrfToken) ?>"><label>Name<input name="name" value="<?= $v('name') ?>" maxlength="150" required><?php if(isset($errors['name'])):?><span class="field-error"><?= $e($errors['name']) ?></span><?php endif;?></label><label>Slug<input name="slug" value="<?= $v('slug') ?>" maxlength="180"><?php if(isset($errors['slug'])):?><span class="field-error"><?= $e($errors['slug']) ?></span><?php endif;?></label><label>Description<textarea name="description" maxlength="10000" rows="6"><?= $v('description') ?></textarea><?php if(isset($errors['description'])):?><span class="field-error"><?= $e($errors['description']) ?></span><?php endif;?></label><label>SEO title<input name="seo_title" value="<?= $v('seo_title') ?>" maxlength="255"><?php if(isset($errors['seo_title'])):?><span class="field-error"><?= $e($errors['seo_title']) ?></span><?php endif;?></label><label>SEO description<textarea name="seo_description" maxlength="320" rows="3"><?= $v('seo_description') ?></textarea><?php if(isset($errors['seo_description'])):?><span class="field-error"><?= $e($errors['seo_description']) ?></span><?php endif;?></label><label class="check"><input type="checkbox" name="is_active" value="1" <?= (int)($values['is_active']??1)===1?'checked':'' ?>> Active</label><button type="submit">Save category</button></form>
